/* Functions copied from quasaore_core to simplify application of Tapenade */
int gb_sd_notnull_c(double x) {
    return (x < 0 || x > 0 ? 1 : 0);
}

int gb_sd_isnull_c(double x) {
    int result1;
    result1 = gb_sd_notnull_c(x);
    return 1 - result1;
}

/*
  Differentiation of gb_sd_omega_fun in forward (tangent) mode:
   variations   of useful results: gb_sd_omega_fun
   with respect to varying inputs: x
*/
double gb_sd_omega_fun_d(double x, double xd, double Delta, double *
        gb_sd_omega_fun) {
    if (Delta < 0.) {
        *gb_sd_omega_fun = tan(x);
        return (1.0+tan(x)*tan(x))*xd;
    } else {
        *gb_sd_omega_fun = tanh(x);
        return (1.0-tanh(x)*tanh(x))*xd;
    }
}

