int gb_sd_constants_d(double a, double ad, double b, double bd, double c,
        double cd, double constants[4], double constantsd[4]) {
    /* Delta (not very robust numerically, see c_quasoare_core for
     * a better formulation */
    double Delta = b*b - 4*a*c;
    double Deltad = 2*b*bd - c*4*ad - 4*a*cd;
    double fabs0;
    double fabs0d;
    double result1;
    double result1d;
    int ii1;
    double temp;
    for (ii1 = 0; ii1 < 4; ++ii1)
        constantsd[ii1] = 0.0;
    constantsd[0] = Deltad;
    constants[0] = Delta;
    /* signD */
    constantsd[1] = 0.0;
    constants[1] = (Delta < 0 ? -1. : 1.);
    if (Delta >= 0.0) {
        fabs0d = Deltad;
        fabs0 = Delta;
    } else {
        fabs0d = -Deltad;
        fabs0 = -Delta;
    }
    /* qD */
    temp = sqrt(fabs0);
    result1d = (fabs0 == 0.0 ? 0.0 : fabs0d/(2.0*temp));
    result1 = temp;
    constantsd[2] = result1d/2;
    constants[2] = result1/2;
    /* sbar */
    temp = b/(2.*a);
    constantsd[3] = -((bd-temp*2.*ad)/(2.*a));
    constants[3] = -temp;
    return 0;
}

