/*
  Differentiation of sd_rr_prod_runtimestep in forward (tangent) mode:
   variations   of useful results: *flux *state
   with respect to varying inputs: gamma *flux x0 *state
   Plus diff mem management of: flux:in state:in
*/
int sd_rr_prod_runtimestep_d(double qstar1, double qstar2, double timestep,
        double gamma, double gammad, double x0, double x0d, double *state,
        double *stated, double *flux, double *fluxd) {
    double temp;
    int ii1;
    double temp0;
    /* Quasaore coefficients
     * dx/dt = Q1* / G (1-x^2) - Q2* / G x(2-x) - 1/?  4^3/9^4 x^2
     *       = a x^2 + b x + c
     *
     * Output flux = Q1* - Q1 - Q2
     * F = Q1* - Q1* (1 - intx2/?) + ?/?^2 4^3/9^4 intx2
     */
    temp = (qstar2-qstar1)/gamma;
    double a = temp - 64./(6561.*timestep);
    double ad = -(temp*gammad/gamma);
    temp = 2*qstar2/gamma;
    double b = -temp;
    double bd = temp*gammad/gamma;
    double c = qstar1/gamma;
    double cd = -(qstar1*gammad/(gamma*gamma));
    double constants[4];
    double constantsd[4];
    for (ii1 = 0; ii1 < 4; ++ii1)
        constantsd[ii1] = 0.0;
    gb_sd_constants_d(a, ad, b, bd, c, cd, constants, constantsd);
    /* Applies Quasaore solution */
    double x1;
    double x1d;
    x1d = gb_sd_forward_d(a, ad, b, bd, c, cd, constants, constantsd, timestep
                          , x0, x0d, &x1);
    *stated = x1d;
    *state = x1;
    /* compute output flux, i.e. Q1*-Q1 + Q3 */
    double integ[2];
    double integd[2];
    for (ii1 = 0; ii1 < 2; ++ii1)
        integd[ii1] = 0.0;
    gb_sd_integrate_x_d(a, ad, b, bd, c, cd, constants, constantsd, timestep,
                        x0, x0d, x1, x1d, integ, integd);
    temp = integ[1]/timestep;
    temp0 = qstar1 + 64.*gamma/(6561.*timestep);
    *fluxd = temp*64.*gammad/(6561.*timestep) + temp0*integd[1]/timestep;
    *flux = temp0*temp;
    return 0;
}

/*
  Differentiation of sd_rr_route_runtimestep in forward (tangent) mode:
   variations   of useful results: *flux *state
   with respect to varying inputs: gamma *flux qstar1 qstar2 x0
                *state
   Plus diff mem management of: flux:in state:in
*/
int sd_rr_route_runtimestep_d(double qstar1, double qstar1d, double qstar2,
        double qstar2d, double timestep, double gamma, double gammad, double
        x0, double x0d, double *state, double *stated, double *flux, double *
        fluxd) {
    /* Quasaore coefficients
     * dx/dt = Q1* / G 0.9 + Q2* / G x^2 - 1/? 0.25 x^2
     *
     * Output flux = Q1* - Q1 - Q3
     * F = 0.1 Q1* + ?/? 0.25 intx2 / ?
     *
     */
    double a = qstar2/gamma - 0.25/timestep;
    double ad = (qstar2d-qstar2*gammad/gamma)/gamma;
    double b = 0.;
    double bd;
    double c = qstar1/gamma*0.9;
    double cd = 0.9*(qstar1d-qstar1*gammad/gamma)/gamma;
    double constants[4];
    double constantsd[4];
    int ii1;
    for (ii1 = 0; ii1 < 4; ++ii1)
        constantsd[ii1] = 0.0;
    bd = 0.0;
    gb_sd_constants_d(a, ad, b, bd, c, cd, constants, constantsd);
    /* Applies Quasaore solution */
    double x1;
    double x1d;
    bd = 0.0;
    x1d = gb_sd_forward_d(a, ad, b, bd, c, cd, constants, constantsd, timestep
                          , x0, x0d, &x1);
    *stated = x1d;
    *state = x1;
    double integ[2];
    double integd[2];
    for (ii1 = 0; ii1 < 2; ++ii1)
        integd[ii1] = 0.0;
    bd = 0.0;
    gb_sd_integrate_x_d(a, ad, b, bd, c, cd, constants, constantsd, timestep,
                        x0, x0d, x1, x1d, integ, integd);
    *fluxd = 0.1*qstar1d + 0.25*(integ[1]*gammad+gamma*integd[1])/(timestep*
        timestep);
    *flux = qstar1*0.1 + gamma*0.25*integ[1]/timestep/timestep;
    return 0;
}

/*
  Differentiation of sd_ro_route_runtimestep in forward (tangent) mode:
   variations   of useful results: *flux *state
   with respect to varying inputs: gamma *flux qstar1 x0 *state
   Plus diff mem management of: flux:in state:in
*/
int sd_ro_route_runtimestep_d(double qstar1, double qstar1d, double timestep,
        double gamma, double gammad, double x0, double x0d, double *state,
        double *stated, double *flux, double *fluxd) {
    /* Quasaore coefficients
     * dx/dt = Q1* / ? - 1/? x^2
     *       = a x^2 + b x + c
     *
     * Output flux = Q1* - Q1 - Q2
     * F = Q1* - Q1* (1 - intx2) + ?/?  4^3/9^4 intx2
     */
    double a = -1./timestep;
    double ad;
    double b = 0;
    double bd;
    double c = qstar1/gamma;
    double cd = (qstar1d-qstar1*gammad/gamma)/gamma;
    double constants[4];
    double constantsd[4];
    int ii1;
    for (ii1 = 0; ii1 < 4; ++ii1)
        constantsd[ii1] = 0.0;
    bd = 0.0;
    ad = 0.0;
    gb_sd_constants_d(a, ad, b, bd, c, cd, constants, constantsd);
    /* Applies Quasaore solution */
    double x1;
    double x1d;
    bd = 0.0;
    ad = 0.0;
    x1d = gb_sd_forward_d(a, ad, b, bd, c, cd, constants, constantsd, timestep
                          , x0, x0d, &x1);
    *stated = x1d;
    *state = x1;
    *fluxd = qstar1d - gamma*(x1d-x0d)/timestep - (x1-x0)*gammad/timestep;
    *flux = qstar1 - gamma/timestep*(x1-x0);
    return 0;
}

/*
  Differentiation of c_gradbench_semidist in forward (tangent) mode:
   variations   of useful results: *qout_rr_prod *qout_rr_route
                *qout_ro_route
   with respect to varying inputs: *gammas_ro_route *gammas_rr_prod
                *gammas_rr_route *demands_rr_route
   RW status of diff variables: gammas_ro_route:(loc) *gammas_ro_route:in
                gammas_rr_prod:(loc) *gammas_rr_prod:in qout_rr_prod:(loc)
                *qout_rr_prod:out qout_rr_route:(loc) *qout_rr_route:out
                gammas_rr_route:(loc) *gammas_rr_route:in qout_ro_route:(loc)
                *qout_ro_route:out demands_rr_route:(loc) *demands_rr_route:in
   Plus diff mem management of: gammas_ro_route:in gammas_rr_prod:in
                states_ro_route:in qout_rr_prod:in qout_rr_route:in
                gammas_rr_route:in states_rr_route:in qout_ro_route:in
                states_rr_prod:in demands_rr_route:in
*/
int c_gradbench_semidist_d(int nval, int nreaches, double timestep, double
        x0_rr_prod, double x0_rr_route, double x0_ro_route, double *areas,
        double *gammas_rr_prod, double *gammas_rr_prodd, double *
        gammas_rr_route, double *gammas_rr_routed, double *gammas_ro_route,
        double *gammas_ro_routed, double *demands_rr_route, double *
        demands_rr_routed, double *pin, double *ein, double *states_rr_prod,
        double *states_rr_prodd, double *states_rr_route, double *
        states_rr_routed, double *states_ro_route, double *states_ro_routed,
        double *qout_rr_prod, double *qout_rr_prodd, double *qout_rr_route,
        double *qout_rr_routed, double *qout_ro_route, double *qout_ro_routed)
{
    int i, j, k;
    double pi, ei, qi;
    double qid;
    double xini_rr_prod, xini_rr_route, xini_ro_route;
    double xini_rr_prodd, xini_rr_routed, xini_ro_routed;
    double qout[1], conversion_factor;
    double qoutd[1];
    int ii1;
    *states_ro_routed = 0.0;
    *qout_rr_prodd = 0.0;
    *qout_rr_routed = 0.0;
    *states_rr_routed = 0.0;
    *qout_ro_routed = 0.0;
    *states_rr_prodd = 0.0;
    for (ii1 = 0; ii1 < 1; ++ii1)
        qoutd[ii1] = 0.0;
    /* Loop through reaches */
    for (i = 0; i < nreaches; ++i) {
        xini_rr_prod = x0_rr_prod;
        xini_rr_route = x0_rr_route;
        xini_ro_route = x0_ro_route;
        /* Convert mm/timestep[days] -> m3/s */
        conversion_factor = areas[i]*timestep/86.4;
        xini_ro_routed = 0.0;
        xini_rr_routed = 0.0;
        xini_rr_prodd = 0.0;
        /* Time series loop */
        for (j = 0; j < nval; ++j) {
            k = j*nreaches + i;
            /* Get inputs for production */
            pi = pin[k];
            ei = ein[k];
            /* Run production */
            sd_rr_prod_runtimestep_d(pi, ei, timestep, gammas_rr_prod[i],
                                     gammas_rr_prodd[i], xini_rr_prod,
                                     xini_rr_prodd, &(states_rr_prod[k]), &(
                                     states_rr_prodd[k]), &(qout_rr_prod[k]),
                                     &(qout_rr_prodd[k]));
            xini_rr_prodd = states_rr_prodd[k];
            xini_rr_prod = states_rr_prod[k];
            /* Run routing */
            qid = qout_rr_prodd[k];
            qi = qout_rr_prod[k];
            sd_rr_route_runtimestep_d(qi, qid, demands_rr_route[i],
                                      demands_rr_routed[i], timestep,
                                      gammas_rr_route[i], gammas_rr_routed[i],
                                      xini_rr_route, xini_rr_routed, &(
                                      states_rr_route[k]), &(states_rr_routed[
                                      k]), &(qout_rr_route[k]), &(
                                      qout_rr_routed[k]));
            xini_rr_routed = states_rr_routed[k];
            xini_rr_route = states_rr_route[k];
            /* Routing model - the first reach is runoff only */
            qid = (i == 0 ? 0.0 : qout_ro_routed[k - 1]);
            qi = (i == 0 ? 0. : qout_ro_route[k - 1]);
            sd_ro_route_runtimestep_d(qi, qid, timestep, gammas_ro_route[i],
                                      gammas_ro_routed[i], xini_ro_route,
                                      xini_ro_routed, &(states_ro_route[k]), &
                                      (states_ro_routed[k]), qout, qoutd);
            xini_ro_routed = states_ro_routed[k];
            xini_ro_route = states_ro_route[k];
            qout_ro_routed[k] = *qoutd + conversion_factor*qout_rr_routed[k];
            qout_ro_route[k] = *qout + qout_rr_route[k]*conversion_factor;
        }
    }
    return 0;
}
